mapper.select:
SELECT n.note_id AS noteId, n.title AS title, IFNULL(n.summary, LEFT(n.content, 200)) AS summary, n.status AS status, n.is_public AS isPublic, n.view_count AS viewCount, n.like_count AS likeCount, n.comment_count AS commentCount, n.reviewed AS reviewed, n.user_id AS userId, u.nickname AS author, u.avatar AS avatar, n.category_id AS categoryId, c.name AS categoryName, n.create_time AS createTime, n.update_time AS updateTime FROM note n INNER JOIN sys_user u ON u.user_id = n.user_id LEFT JOIN sys_category c ON c.category_id = n.category_id WHERE n.del_flag = 0
AND n.status = #{query.status}
AND n.category_id = #{query.categoryId}
AND (n.title LIKE CONCAT('%', #{query.keyword}, '%') OR n.content LIKE CONCAT('%', #{query.keyword}, '%'))
AND n.user_id = #{query.userId}
AND n.create_time >= #{query.startTime}
AND n.create_time <= #{query.endTime}
AND n.reviewed = #{query.reviewed}
ORDER BY n.create_time DESC

